import { Suspense } from 'react'
import { ShellSkeleton, CardStatsSkeleton, RevenueChartSkeleton, LatestInvoicesSkeleton } from './_components/skeletons'
import { CardStats } from './CardStats'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'

async function getCardStats() {
  const res = await fetch('https://api.example.com/dashboard/stats', { cache: 'no-store' })
  return res.json()
}

async function getRevenueChart() {
  const res = await fetch('https://api.example.com/dashboard/revenue', { cache: 'no-store' })
  return res.json()
}

async function getLatestInvoices() {
  const res = await fetch('https://api.example.com/dashboard/invoices', { cache: 'no-store' })
  return res.json()
}

function DashboardHeader() {
  return (
    <div className="mb-6 flex items-center justify-between">
      <h1 className="text-2xl font-bold">Dashboard</h1>
      <span className="text-sm text-gray-500">Last updated: just now</span>
    </div>
  )
}

function CardStatsSection() {
  return (
    <Suspense fallback={<CardStatsSkeleton />}>
      <CardStatsData />
    </Suspense>
  )
}

async function CardStatsData() {
  const data = await getCardStats()
  return <CardStats totalRevenue={data.totalRevenue} totalInvoices={data.totalInvoices} />
}

function RevenueChartSection() {
  return (
    <Suspense fallback={<RevenueChartSkeleton />}>
      <RevenueChartData />
    </Suspense>
  )
}

async function RevenueChartData() {
  const data = await getRevenueChart()
  return <RevenueChart revenue={data} />
}

function LatestInvoicesSection() {
  return (
    <Suspense fallback={<LatestInvoicesSkeleton />}>
      <LatestInvoicesData />
    </Suspense>
  )
}

async function LatestInvoicesData() {
  const data = await getLatestInvoices()
  return <LatestInvoices invoices={data} />
}

export default async function Page() {
  return (
    <main className="p-6">
      <DashboardHeader />
      <CardStatsSection />
      <RevenueChartSection />
      <LatestInvoicesSection />
    </main>
  )
}

